function HealthStory() {
  const [active, setActive] = useState(0);
  const [expanded, setExpanded] = useState<number | null>(null);
  const started = useMemo(() => Date.now(), []);
  const stages = [
    ["01", "INGESTION", "12,408 signals received", "Raw signals are captured, timestamped, and attached to the application context before anything is evaluated.", "2.4M events", "blue", "captured"],
    ["02", "NORMALIZATION", "Trace shape verified", "The events become one ordered execution story. Retrieval, model, state, and tool calls now share the same timeline.", "99.98% valid", "violet", "understood"],
    ["03", "EVALUATION", "Signals are being scored", "Groundedness, policy compliance, safety, and workflow integrity are evaluated in parallel.", "4 evaluators", "amber", "evaluated"],
    ["04", "DECISION", "Release signal ready", "The evidence is handed to the release gate. The result is preserved as a defensible PASS, REVIEW, or BLOCK.", "92% healthy", "mint", "trusted"],
  ];
  useEffect(() => {
    const tick = () => setActive(Math.floor(((Date.now() - started) % 7600) / 1900));
    tick();
    const timer = window.setInterval(tick, 100);
    return () => window.clearInterval(timer);
  }, [started]);
  const desktopPath = "M 88 188 C 176 88, 245 88, 332 188 S 490 288, 576 188 S 730 88, 818 188";
  const mobilePath = "M 132 50 C 46 130, 218 185, 132 265 S 46 395, 132 480 S 218 600, 132 710";
  return <><PageHeading eyebrow="SYSTEM VITALS / LIVE STORY" title="Reliability Story" description="Watch one signal move from raw input to trusted action across the TrustOps pipeline." actions={<button onClick={() => go("overview")} className="ghost-button"><ChevronRight size={13} className="rotate-180"/> Back to overview</button>}/>
    <section className="journey-shell">
      <div className="journey-intro"><div><span className="pipeline-kicker">ONE SIGNAL / FOUR HANDOFFS</span><h2>From raw signal<br/>to <span className="gradient-word">trusted action.</span></h2><p>The signal is not four separate metrics. It is one story being handed forward — captured, understood, evaluated, and made safe to act on.</p></div><div className="journey-live"><span className="live-dot"/>LIVE JOURNEY<div className="journey-live-bar"><i/><i/><i/><i/></div><small>{stages[active][1]} / {stages[active][6]}</small></div></div>
      <div className="journey-canvas">
        <div className="journey-label label-raw">RAW SIGNAL<span>captured</span></div><div className="journey-label label-trusted">TRUSTED ACTION<span>ready to ship</span></div>
        <svg className="journey-svg journey-svg-desktop" viewBox="0 0 900 340" preserveAspectRatio="none" aria-hidden="true"><path className="journey-path-base" d={desktopPath}/><path className="journey-path-trail" d={desktopPath} style={{strokeDashoffset: `${Math.max(0, (3-active)*-170)}`}}/><circle className="journey-signal" r="7"><animateMotion dur="7.6s" repeatCount="indefinite" path={desktopPath} rotate="auto"/></circle><circle className="journey-signal-core" r="2.2"><animateMotion dur="7.6s" repeatCount="indefinite" path={desktopPath} rotate="auto"/></circle></svg>
        <svg className="journey-svg journey-svg-mobile" viewBox="0 0 264 760" preserveAspectRatio="none" aria-hidden="true"><path className="journey-path-base" d={mobilePath}/><path className="journey-path-trail" d={mobilePath}/><circle className="journey-signal" r="7"><animateMotion dur="7.6s" repeatCount="indefinite" path={mobilePath} rotate="auto"/></circle></svg>
        <div className="journey-stages">{stages.map(([num,label,title,copy,stat,color,state],i)=><motion.button key={label} onClick={() => setExpanded(expanded===i ? null : i)} animate={{y: active===i ? -7 : 0, scale: active===i ? 1.015 : 1}} transition={{type:"spring",stiffness:280,damping:24}} className={`journey-stage ${color} ${active===i ? "journey-stage-active" : ""} ${active>i ? "journey-stage-complete" : ""}`}><div className="journey-stage-top"><span>{num}</span><span className="journey-state">{active===i ? "SIGNAL HERE" : active>i ? "✓ COMPLETED" : "AWAITING"}</span></div><div className="journey-stage-number">{num}</div><h3>{label}</h3><strong>{title}</strong><p>{copy}</p><div className="journey-stage-footer"><b>{stat}</b><span>{expanded===i ? "CLOSE" : "OPEN CHAPTER"} <ChevronRight size={11}/></span></div></motion.button>)}</div>
      </div>
      <AnimatePresence mode="wait">{expanded !== null && <motion.div key={expanded} initial={{opacity:0,height:0,y:-8}} animate={{opacity:1,height:"auto",y:0}} exit={{opacity:0,height:0,y:-8}} transition={{duration:.28,ease:[.23,1,.32,1]}} className="journey-detail"><div className={`journey-detail-marker ${stages[expanded][5]}`}>{stages[expanded][0]}</div><div><span className="pipeline-kicker">CHAPTER {stages[expanded][0]} / {stages[expanded][1]}</span><h3>{stages[expanded][2]}</h3><p>{stages[expanded][3]}</p></div><div className="journey-detail-data"><b>{stages[expanded][4]}</b><span>current signal</span></div></motion.div>}</AnimatePresence>
    </section>
    <div className="story-bottom-grid"><Panel><PanelTitle title="Current signal mix" subtitle="Last 30 minutes"/><div className="signal-mix"><div><span>PASS</span><b>78%</b><i className="mix-pass" style={{width:"78%"}}/></div><div><span>REVIEW</span><b>16%</b><i className="mix-review" style={{width:"16%"}}/></div><div><span>BLOCK</span><b>6%</b><i className="mix-block" style={{width:"6%"}}/></div></div></Panel><Panel><PanelTitle title="If the signal changes" subtitle="TrustOps response"/><div className="response-list"><div><span className="response-icon blue">1</span><p><b>Capture the change</b><small>Preserve the trace and context.</small></p></div><div><span className="response-icon violet">2</span><p><b>Find the cause</b><small>Rank evidence and failure classes.</small></p></div><div><span className="response-icon mint">3</span><p><b>Protect the release</b><small>Gate the decision with confidence.</small></p></div></div></Panel></div></>;
}
export default function Home() { const [path, setPath] = useState(window.location.pathname); useEffect(() => { const handler = () => setPath(window.location.pathname); window.addEventListener("popstate", handler); return () => window.removeEventListener("popstate", handler); }, []); const active = useMemo<NavKey>(() => { const p = path.split("/")[1] as NavKey; return navItems.some(n => n.key === p) ? p : "overview"; }, [path]); let page: React.ReactNode; if (path === "/" || path === "") page = <Landing/>; else if (path === "/health") page = <HealthStory/>; else if (active === "overview") page = <Overview/>; else if (active === "applications") page = <Applications/>; else if (active === "traces") page = <Traces/>; else if (active === "detail") page = <TraceDetail/>; else if (active === "rag") page = <Rag/>; else if (active === "rca") page = <RCA/>; else if (path === "/health") page = <HealthStory/>; else page = <Gate/>; return path === "/" || path === "" ? page : <AppShell active={active}>{page}</AppShell>; }
